	function SaveAllAttachments($dirPath) {
		return CkEmail_SaveAllAttachments($this->_cPtr,$dirPath);
	}

	/**
	 * Saves the attachment at the zero-based index specified by ARG1 to the directory specified by ARG2. If ARG2 or any of its directory components do not exist, Chilkat creates them automatically. The OverwriteExisting property controls whether an existing file may be overwritten.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkEmailRef.html#SaveAttachedFile
	 * @param int $index
	 * @param ?string $dirPath
	 * @return bool
	 */
	function SaveAttachedFile($index,$dirPath) {
		return CkEmail_SaveAttachedFile($this->_cPtr,$index,$dirPath);
	}

	/**
	 * Convert this email object to EML and save it to a file.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkEmailRef.html#SaveEml
	 * @param ?string $emlFilePath
	 * @return bool
	 */
	function SaveEml($emlFilePath) {
		return CkEmail_SaveEml($this->_cPtr,$emlFilePath);
	}

	/**
	 * Saves the related item at the zero-based index specified by ARG1 to the directory specified by ARG2. If ARG2 or any of its directory components do not exist, Chilkat creates them automatically. Valid indexes are from 0 through NumRelatedItems - 1. The OverwriteExisting property controls whether an existing file may be overwritten.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkEmailRef.html#SaveRelatedItem
	 * @param int $index
	 * @param ?string $dirPath
	 * @return bool
	 */
	function SaveRelatedItem($index,$dirPath) {
