	 * Convert this email object to XML and save it to a file.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkEmailRef.html#SaveXml
	 * @param ?string $path
	 * @return bool
	 */
	function SaveXml($path) {
		return CkEmail_SaveXml($this->_cPtr,$path);
	}

	/**
	 * Sets the charset parameter of the Content-Type header field for the attachment at the zero-based index specified by ARG1. ARG2 specifies the charset, such as Shift_JIS, iso-8859-2, big5, or iso-8859-5.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkEmailRef.html#SetAttachmentCharset
	 * @param int $index
	 * @param ?string $charset
	 * @return bool
	 */
	function SetAttachmentCharset($index,$charset) {
		return CkEmail_SetAttachmentCharset($this->_cPtr,$index,$charset);
	}

	/**
	 * Sets the Content-Disposition value for the attachment at the zero-based index specified by ARG1.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkEmailRef.html#SetAttachmentDisposition
	 * @param int $index
	 * @param ?string $disposition
	 * @return bool
	 */
	function SetAttachmentDisposition($index,$disposition) {
		return CkEmail_SetAttachmentDisposition($this->_cPtr,$index,$disposition);
	}

	/**
	 * Changes the filename of the attachment at the zero-based index specified by ARG1. ARG2 contains the new filename.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkEmailRef.html#SetAttachmentFilename
	 * @param int $index
	 * @param ?string $filename
	 * @return bool
	 */
	function SetAttachmentFilename($index,$filename) {
		return CkEmail_SetAttachmentFilename($this->_cPtr,$index,$filename);
	}

	/**
	 * Sets the main email body to binary content. ARG1 contains the body bytes, and ARG2 specifies the MIME Content-Type.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkEmailRef.html#SetBinaryBody
	 * @param CkByteData $byteData
