	}

	/**
	 * Sets the main email body from the binary data in ARG1.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkEmailRef.html#SetBodyBd
	 * @param CkBinData $bd
	 * @param ?string $contentType
	 * @param ?string $disposition
	 * @param ?string $filename
	 * @return bool
	 */
	function SetBodyBd($bd,$contentType,$disposition,$filename) {
		return CkEmail_SetBodyBd($this->_cPtr,$bd,$contentType,$disposition,$filename);
