	/**
	 * Allows for a certificate to be explicitly provided for decryption. When an email object is loaded via any method, such as LoadEml, SetFromMimeText, SetFromMimeBytes, etc., security layers (signatures and encryption) are automatically unwrapped. This method could be called prior to calling a method that loads the email.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkEmailRef.html#SetDecryptCert
	 * @param CkCert $cert
	 * @return bool
	 */
	function SetDecryptCert($cert) {
		return CkEmail_SetDecryptCert($this->_cPtr,$cert);
	}

	/**
	 * Explicitly provides the certificate in ARG1 and the corresponding private key in ARG2 for decryption. When an email object is loaded by a method such as LoadEml, SetFromMimeText, or SetFromMimeBytes, security layers such as signatures and encryption are automatically unwrapped. Decryption requires the private key in ARG2.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkEmailRef.html#SetDecryptCert2
	 * @param CkCert $cert
	 * @param CkPrivateKey $key
	 * @return bool
	 */
	function SetDecryptCert2($cert,$key) {
		return CkEmail_SetDecryptCert2($this->_cPtr,$cert,$key);
	}

