	function SetTextBody($bodyText,$contentType) {
		CkEmail_SetTextBody($this->_cPtr,$bodyText,$contentType);
	}

	/**
	 * Creates a new Delivery Status Notification (DSN) email in the format specified by RFC 3464. The DSN email is generated in ARG4.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkEmailRef.html#ToDsn
	 * @param ?string $explanation
	 * @param ?string $statusFields
	 * @param bool $headerOnly
	 * @param CkEmail $dsnEmail
	 * @return bool
	 */
	function ToDsn($explanation,$statusFields,$headerOnly,$dsnEmail) {
		return CkEmail_ToDsn($this->_cPtr,$explanation,$statusFields,$headerOnly,$dsnEmail);
	}

