	 * Creates an inline-forward email in ARG1 based on this email.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkEmailRef.html#ToForward
	 * @param CkEmail $forward
	 * @return bool
	 */
	function ToForward($forward) {
		return CkEmail_ToForward($this->_cPtr,$forward);
	}

	/**
	 * Creates a new MDN (Message Disposition Notification) email in ARG4 using the format specified by RFC 3798.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkEmailRef.html#ToMdn
	 * @param ?string $message
	 * @param ?string $statusFields
	 * @param bool $headerOnly
	 * @param CkEmail $mdn
	 * @return bool
	 */
	function ToMdn($message,$statusFields,$headerOnly,$mdn) {
		return CkEmail_ToMdn($this->_cPtr,$message,$statusFields,$headerOnly,$mdn);
	}

