	 * Generates a reply email in ARG1 with updated header and body fields to enable sending as a reply. Note: Attachments are excluded from the reply, but attached messages are included. To exclude attached messages, call RemoveAttachedMessages on the reply email object.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkEmailRef.html#ToReply
	 * @param CkEmail $reply
	 * @return bool
	 */
	function ToReply($reply) {
		return CkEmail_ToReply($this->_cPtr,$reply);
	}

	/**
	 * Returns _TRUE_ if this email's UIDL equals the UIDL of the email passed in ARG1.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkEmailRef.html#UidlEquals
	 * @param CkEmail $e
	 * @return bool
	 */
	function UidlEquals($e) {
		return CkEmail_UidlEquals($this->_cPtr,$e);
	}

	/**
	 * Unpacks an HTML email into an HTML file and separate related files, such as images and style sheets. Links in the HTML are rewritten to reference the extracted files.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkEmailRef.html#UnpackHtml
	 * @param ?string $unpackDir
	 * @param ?string $htmlFilename
	 * @param ?string $partsSubdir
	 * @return bool
	 */
	function UnpackHtml($unpackDir,$htmlFilename,$partsSubdir) {
		return CkEmail_UnpackHtml($this->_cPtr,$unpackDir,$htmlFilename,$partsSubdir);
	}

	/**
	 * Unobfuscates emails by undoing what spammers do to obfuscate email. It removes comments from HTML bodies and unobfuscates hyperlinked URLs.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkEmailRef.html#UnSpamify
	 */
	function UnSpamify() {
		CkEmail_UnSpamify($this->_cPtr);
	}

	/**
	 * Unzips and replaces any Zip file attachments with the expanded contents. As an example, if an email contained a single Zip file containing 3 GIF image files as an attachment, then after calling this method the email would contain 3 GIF file attachments, and the Zip attachment would be gone.If an email contains multiple Zip file attachments, each Zip is expanded and replaced with the contents.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkEmailRef.html#UnzipAttachments
	 * @return bool
	 */
	function UnzipAttachments() {
		return CkEmail_UnzipAttachments($this->_cPtr);
	}

	/**
	 * Adds the XML certificate vault in ARG1 to the object's internal certificate and private-key lookup sources for encryption, decryption, signing, and verification.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkEmailRef.html#UseCertVault
	 * @param CkXmlCertVault $vault
	 * @return bool
	 */
	function UseCertVault($vault) {
		return CkEmail_UseCertVault($this->_cPtr,$vault);
	}

	/**
	 * Replaces all the attachments of an email with a single Zip file attachment having the filename specified.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkEmailRef.html#ZipAttachments
	 * @param ?string $zipFilename
	 * @return bool
	 */
	function ZipAttachments($zipFilename) {
		return CkEmail_ZipAttachments($this->_cPtr,$zipFilename);
	}
}
